<?php
/**
 * Вымышленные оборотно-сальдовые ведомости 1С (.xls) для теста импорта — та же раскладка, что у выгрузок хосписа:
 *  - osv-10.xls, счет 10 (материалы): на позицию две строки — «Название | сумма» и «Кол-во | количество»;
 *  - osv-01.xls, счет 01 (основные средства): строка на единицу «Название, инв.№: номер».
 * Запуск внутри web-контейнера стенда (нужен PhpSpreadsheet):
 *   docker cp make-1c.php squirrelstock-web-1:/tmp/ && docker exec squirrelstock-web-1 php /tmp/make-1c.php /tmp
 *   docker cp squirrelstock-web-1:/tmp/osv-10.xls . && docker cp squirrelstock-web-1:/tmp/osv-01.xls .
 */
require '/var/www/html/vendor/autoload.php';

$dir = $argv[1] ?? '.';

function save(array $rows, string $file) {
    $book = new \PhpOffice\PhpSpreadsheet\Spreadsheet();
    $sheet = $book->getActiveSheet();
    foreach ($rows as $r => $row) {
        foreach ($row as $c => $v) {
            $sheet->setCellValue([$c + 1, $r + 1], $v);
        }
    }
    (new \PhpOffice\PhpSpreadsheet\Writer\Xls($book))->save($file);
}

save([
    ['Учреждение (тест)'],
    ['Оборотно-сальдовая ведомость по счету 10.1 за Сентябрь 2026 г.'],
    ['Выводимые данные: БУ (данные бухгалтерского учета)'],
    ['Отбор: Счет В группе "10.1" И Место хранения Равно "Склад (тест)"'],
    ['Счет', 'Сальдо на начало периода'],
    ['Номенклатура', 'Дебет', 'Кредит'],
    ['Показатели'],
    ['10.1 (по счету: 10)', 1250.5],
    ['Кол-во', 38],
    ['Перчатки тестовые нестерильные размер M', 300.5],
    ['Кол-во', 30],
    ['Шприц тестовый 10 мл', 950],
    ['Кол-во', 8],
    ['Салфетки тестовые (остаток суммы без количества)', 12],
    ['Кол-во', ''],
    ['Итого развернутое', 1262.5],
    ['Кол-во', 38],
], $dir . '/osv-10.xls');

// цена = сумма / количество не делится до копейки: 108,37 / 900 = 0,120411…, 100,00 / 3 = 33,333… (тест partion-price)
save([
    ['Учреждение (тест)'],
    ['Оборотно-сальдовая ведомость по счету 10.1 за Сентябрь 2026 г.'],
    ['Счет', 'Сальдо на начало периода'],
    ['Номенклатура', 'Дебет', 'Кредит'],
    ['Показатели'],
    ['10.1 (по счету: 10)', 208.37],
    ['Кол-во', 903],
    ['Бинт тестовый стерильный 7x14', 108.37],
    ['Кол-во', 900],
    ['Пластырь тестовый рулонный', 100],
    ['Кол-во', 3],
    ['Итого развернутое', 208.37],
    ['Кол-во', 903],
], $dir . '/osv-10-exact.xls');

save([
    ['Учреждение (тест)'],
    ['Оборотно-сальдовая ведомость по счету 01.1 за 26.05.26'],
    ['Счет', 'Сальдо на начало периода'],
    ['Основные средства', 'Дебет', 'Кредит'],
    ['01.1 (по счету: 01)', 3000],
    ['Концентратор кислорода тестовый, инв.№: 01140001', 1000],
    ['Концентратор кислорода тестовый, инв.№: 01140002', 1000],
    ['Кровать функциональная тестовая, инв.№: 77', 1000],
    ['Итого развернутое', 3000],
], $dir . '/osv-01.xls');
echo "ok\n";
